pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v, uint256 w) internal {
        bool firstReverted;
        try c.SetMinSum(v) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool secondReverted;
        try c.SetMinSum(w) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(!firstReverted && afterFirst == v && secondReverted);
    }

    function testFuzz_run(uint256 v, uint256 w) public {
        _run(v, w);
    }

    receive() external payable {}
}
